with kept_keys as (select id, country from customers intersect all select id, country from customers where signup_date between '2023-04-01' and '2024-03-01'), verified as (select s.* from customers s inner join kept_keys k on s.id = k.id and s.country = k.country) select id, name, email, country, city, segment, is_active, age, case when segment rlike '^(Consumer|Corporate)$' then 'GROUP_A' when segment rlike '^(SMB)$' then 'EXTENDED' else 'OTHER_ZONE' end as segment_zone from verified order by age desc;
